import { describe, expect, it } from "vitest";
import fixtureJson from "../../examples/default-workspace.json";
import observablesFixture from "../../examples/observables.json";
import { assignmentSchema, controlSchema, feedbackReviewSchema, frameSchema, isStateRule, posKey, workspaceSchema } from "./schema";

// Generated by the Rust runtime (`cargo run --example dump_workspace`) and
// guarded against drift by a Rust test, so this is the real IPC contract.
const fixture: unknown = fixtureJson;

describe("workspace contract with Rust", () => {
  const ws = workspaceSchema.parse(fixture);

  it("parses the default workspace emitted by Rust", () => {
    expect(ws.schemaVersion).toBe(4);
    expect(ws.surfaces.map((s) => s.id)).toEqual(expect.arrayContaining(["agent-control", "development", "productivity", "accessibility", "smart-home"]));
  });

  it("has unique control ids and positions on every page", () => {
    for (const s of ws.surfaces)
      for (const p of s.pages) {
        expect(new Set(p.controls.map((c) => c.id)).size, `${s.id}/${p.id} ids`).toBe(p.controls.length);
        expect(new Set(p.controls.map((c) => posKey(c.pos))).size, `${s.id}/${p.id} positions`).toBe(p.controls.length);
      }
  });

  it("gives the Agent Control surface one pad per status, reading Agent Control's own states", () => {
    const surface = ws.surfaces.find((s) => s.id === "agent-control")!;
    expect(surface.category).toBe("agents");
    const home = surface.pages[0]!;
    const slots = home.controls.filter((c) => c.pos.kind === "grid" && c.pos.row === 0 && c.pos.col < 8);
    expect(slots).toHaveLength(8);
    for (const slot of slots) {
      // Every normalized status has a look, plus the empty slot. Nothing here names a provider.
      expect(Object.keys(slot.states).sort()).toEqual(
        ["approval_required", "cancelled", "completed", "empty", "failed", "idle", "offline", "paused", "running", "starting", "tool_use", "waiting"].sort(),
      );
      expect(slot.feedback).toHaveLength(1);
      expect(slot.feedback.every((r) => isStateRule(r) && r.when.state.provider === "agent-control")).toBe(true);
      expect(slot.legacyBindings).toEqual([]);
    }
    const approve = home.controls.find((c) => c.label === "Approve")!;
    expect(Object.keys(approve.states).sort()).toEqual(["attention", "available", "failed", "pending", "succeeded", "unavailable"]);
    expect(approve.states["attention"]?.animation).toBe("flash"); // the pad that asks for you
    expect(approve.states["unavailable"]?.animation).toBe("none");
    expect(JSON.stringify(surface).toLowerCase()).not.toMatch(/claude|codex|openai|anthropic/);
  });

  it("makes accessibility targets large and few", () => {
    const home = ws.surfaces.find((s) => s.id === "accessibility")!.pages[0]!;
    const grid = home.controls.filter((c) => c.pos.kind === "grid");
    expect(grid.length).toBeGreaterThan(0);
    expect(grid.length).toBeLessThanOrEqual(12);
    expect(grid.every((c) => c.span.w >= 2 && c.span.h >= 2)).toBe(true);
  });

  it("round-trips through the schema without losing data", () => {
    expect(workspaceSchema.parse(JSON.parse(JSON.stringify(ws)))).toEqual(ws);
  });
});

describe("schema validation", () => {
  it("stores an assignment as provider, action and settings, and nothing else", () => {
    expect(assignmentSchema.parse({ provider: "system", action: "openUrl" })).toEqual({ provider: "system", action: "openUrl", args: {} });
    expect(assignmentSchema.safeParse({ type: "rm-rf" }).success).toBe(false);
    expect(assignmentSchema.safeParse({ provider: "system", action: "openUrl", args: [1] }).success).toBe(false);
    for (const s of workspaceSchema.parse(fixture).surfaces)
      for (const p of s.pages)
        for (const c of p.controls)
          for (const a of [c.press, c.longPress])
            if (a) expect(Object.keys(a).sort(), `${s.id}/${c.label}`).toEqual(["action", "args", "provider"]);
  });

  it("rejects malformed colours", () => {
    expect(controlSchema.safeParse({ id: "x", pos: { kind: "grid", col: 0, row: 0 }, label: "x", visual: { color: "red" } }).success).toBe(false);
  });

  it("accepts the frame shape the Rust renderer emits", () => {
    const ok = frameSchema.safeParse({ leds: [{ pos: { kind: "top", index: 3 }, led: { color: "#112233", animation: "pulse" } }] });
    expect(ok.success).toBe(true);
  });

  it("builds stable position keys that match Rust", () => {
    expect(posKey({ kind: "grid", col: 3, row: 4 })).toBe("g.3.4");
    expect(posKey({ kind: "top", index: 0 })).toBe("t.0");
    expect(posKey({ kind: "side", index: 7 })).toBe("s.7");
    expect(posKey({ kind: "logo" })).toBe("logo");
  });
});

// What `review_feedback` answers, as Rust emits it (examples/observables.json, checked
// from the Rust side by tests/observables_contract.rs). The editor reads these shapes.
describe("review_feedback contract with Rust", () => {
  it("parses the verdict of a clean draft: the limits are Rust's, nothing to report", () => {
    const review = feedbackReviewSchema.parse(observablesFixture.review.clean);
    expect(review.issues).toEqual([]);
    expect(review.notes).toEqual([]);
    expect(review.preview).toBeNull();
    expect(review.limits).toEqual({ maxRules: 32, maxLookName: 40, maxWhere: 8, defaultHoldMs: 3000, minHoldMs: 200, maxHoldMs: 60000 });
  });

  it("parses what saving would refuse, with the part of the rule each message is about", () => {
    const review = feedbackReviewSchema.parse(observablesFixture.review.draft);
    expect(review.issues.map((i) => [i.rule, i.field])).toEqual([
      [3, "state"],
      [5, "test"],
      [6, "look"],
      [7, "args"],
    ]);
    expect(review.issues[3]!.param).toBe("channel");
  });

  it("parses the four things Rust can prove about a rule", () => {
    const review = feedbackReviewSchema.parse(observablesFixture.review.draft);
    expect(review.notes.map((n) => n.kind).sort()).toEqual(["missingLook", "missingObservable", "providerUnavailable", "shadowed"]);
    expect(review.notes.find((n) => n.kind === "shadowed")).toEqual({ kind: "shadowed", rule: 1, by: 0 });
    expect(review.notes.find((n) => n.kind === "providerUnavailable")).toMatchObject({ provider: "example.hello", reason: "The plugin is turned off in Plugins." });
  });

  it("carries the draft's own explanation when its rules differ from the saved ones", () => {
    const review = feedbackReviewSchema.parse(observablesFixture.review.draft);
    expect(review.preview?.rules.length).toBeGreaterThan(3);
    expect(review.preview?.layer).toBe("state");
  });

  it("refuses a note it does not know, instead of showing something the editor cannot explain", () => {
    expect(feedbackReviewSchema.safeParse({ ...observablesFixture.review.clean, notes: [{ kind: "mystery", rule: 0 }] }).success).toBe(false);
  });
});
